nums = [4, 1, 3]
swaps = 0
for i in range(len(nums) - 1):
    m = i
    for j in range(i + 1, len(nums)):
        if nums[j] < nums[m]:
            m = j
    if m != i:
        nums[i], nums[m] = nums[m], nums[i]
        swaps += 1
print(swaps, nums)

nums = [4, 3, 2, 1]
n = len(nums)
for j in range(n - 1):
    if nums[j] > nums[j + 1]:
        nums[j], nums[j + 1] = nums[j + 1], nums[j]
print(nums)

